import{_ as i,l as s,o as a,c as n,v as r,p as l,x as t,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"退休与精确异常","description":"","frontmatter":{"title":"退休与精确异常","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/retire-precise-exception.md","filePath":"cs/retire-precise-exception.md","lastUpdated":1789023840000}'),E={name:"cs/retire-precise-exception.md"};function h(m,e,A,B,_,u){const o=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="退休与精确异常" tabindex="-1">退休与精确异常 <a class="header-anchor" href="#退休与精确异常" aria-label="Permalink to &quot;退休与精确异常&quot;">​</a></h1><div class="epigraph"><p>乱序可以乱算，对程序员可见的写必须按程序序提交；异常发生时，那条指令之前全部完成、之后全部像没发生。</p><footer>—— 据 Smith and Pleszkun, Implementing Precise Interrupts in Pipelined Processors, ISCA 1985 整理</footer></div><p><a href="/cs/macro-micro-fusion">上一课</a>让内部 uop 数可以少于 ISA 条数，但调试与 trap 仍要按指令边界说话。<a href="/cs/ooo-rob">ROB</a> 与<a href="/cs/speculation-recovery">推测恢复</a> 已经给出冲刷通道。本课不重讲融合白名单。缺口是把<strong>退休（retire / commit）当作架构状态的唯一入口</strong>，并钉精确异常与中断在乱序核上的含义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五级流水的异常可以在某一级「当场停、当场改 PC」。乱序里年轻 <code>add</code> 可能已经写了物理寄存器，年长 <code>load</code> 才缺页。若把物理堆当成架构堆，处理程序会看见未来的 <code>x1</code>。缺口不是再加一个 IQ，而是<strong>只有 ROB 头完成且无异常时，才把结果变成架构可见</strong>——包括整数寄存器、store 对 cache、CSR 副作用。</p><p><span class="marginnote">Smith–Pleszkun 给出 ROB、未来文件、历史缓冲三条路。当代乱序核用 ROB + 物理寄存器堆：提交时更新架构映射或释放旧物理号，store 此刻才离开 SQ。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每拍检查 ROB 头最多 \\(R\\) 条：已执行完毕、无故障则退休——写架构可见状态、释放 <a href="/cs/prf-free-list">PRF</a> 旧槽、弹出 LQ/SQ 头。头指令故障：冲刷头之后全部，把异常 PC 与原因交给特权入口，与<a href="/cs/pipeline-exception">流水线异常</a> 的精确性定义一致。中断：等到一个精确边界（通常某条已退休之后）再插入。</p>',8)),(a(),l(d,null,{default:t(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HEAD%5B%22ROB%20%E5%A4%B4%22%5D%20--%3E%7C%22%E5%AE%8C%E6%88%90%E4%B8%94%E6%97%A0%E6%95%85%E9%9A%9C%22%7C%20RET%5B%22%E9%80%80%E4%BC%91%EF%BC%9A%E6%9E%B6%E6%9E%84%E5%86%99%20%2F%20store%20%E5%8F%AF%E8%A7%81%22%5D%0A%20%20HEAD%20--%3E%7C%22%E6%95%85%E9%9A%9C%22%7C%20TRAP%5B%22%E5%86%B2%E5%88%B7%E5%B9%B4%E8%BD%BB%E9%A1%B9%EF%BC%8C%E8%BF%9B%E9%99%B7%E9%98%B1%22%5D%0A%20%20HEAD%20--%3E%7C%22%E6%9C%AA%E5%AE%8C%E6%88%90%22%7C%20STALL%5B%22%E6%95%B4%E6%A0%B8%E6%8F%90%E4%BA%A4%E5%81%9C%E9%A1%BF%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>提交带宽 \\(R\\) 是第五个窗口上限：执行再快，头被长延迟 load 堵住则 ROB 满，前端停。这与「精确」不可分割：不允许头后面的 store 先可见来「缓解」堵住——那会破坏精确性与 <a href="/cs/mesi-protocol">MESI</a> 的提交即全局。</p><p><a href="/cs/macro-micro-fusion">融合</a> 的指令必须在其架构边界上一次退休或一次 trap：不能出现「比较已经架构可见、分支还在 ROB 里」的半态，除非 ISA 把它们定义成一条。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux 的 trap 处理、信号帧写进来，那是 OS 课。也不处理非精确的浮点状态位实现（有的 ISA 允许推迟）。深流水把核对点推远，退休相对 IF 的距离变长，下一课才谈频率与级深。</p><p>后课默认：架构状态只在退休时变；异常精确 = ROB 头纪律。级越深，同一误预测扔掉的投机量越大。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>退休是架构写的唯一门；异常在 ROB 头精确。</li><li>提交宽度与头阻塞决定何时窗口满。</li><li>级深与时钟的交易是下一课。</li><li>出处：Smith and Pleszkun, <em>ISCA</em>, 1985；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',8))])}const P=i(E,[["render",h]]);export{C as __pageData,P as default};
